def bearer_token(header):
    parts=header.strip().split(None,1)
    return parts[1].strip() if len(parts)==2 and parts[0].lower()=='bearer' else None

def wordpress_slug(title):
    import re
    return re.sub('[^a-z0-9]+','-',title.lower()).strip('-')

def safe_json_object(text):
    import json
    try:
        value=json.loads(text)
        return value if isinstance(value,dict) else {}
    except ValueError:
        return {}

def parse_env_line(line):
    line=line.strip()
    if not line or line.startswith('#') or '=' not in line:return None
    key,value=line.split('=',1)
    return key.strip(),value.strip()

def batch_records(items,size):
    if size<1:raise ValueError('size')
    return [items[i:i+size] for i in range(0,len(items),size)]

def safe_filename(name):
    import re
    return re.sub('[^a-zA-Z0-9_.-]+','_',name).lstrip('.') or 'untitled'
